indexCases:
interface GoodTemplate { [key: `x-${string}`]: number; unrelated: string }
interface BadTemplate {
  [key: `x-${string}`]: number;
  // @ts-expect-error 匹配索引的属性仍须满足其值类型。
  'x-bad': string;
}
interface BadNumber {
  [key: number]: string;
  // @ts-expect-error 数字属性必须匹配数字索引。
  0: number;
}
declare const token: unique symbol;
interface BadSymbol {
  [key: symbol]: number;
  // @ts-expect-error unique symbol 属性也要检查。
  [token]: string;
}
class StaticIndex {
  static [key: `x-${string}`]: number;
  static unrelated = 'valid';
  // @ts-expect-error 静态索引同样约束匹配的静态属性。
  static 'x-bad' = 'invalid';
}
class PrivateField { [key: string]: number; #private = 'valid'; public count = 1; }
interface BaseMember { 'x-bad': string }
// @ts-expect-error 索引需约束从另一个基类继承的属性。
interface Inherited extends BaseMember { [key: `x-${string}`]: number }
interface OtherBase { unrelated: string }
interface GoodInherited extends OtherBase { [key: `x-${string}`]: number }
export type Cases = GoodTemplate | BadTemplate | BadNumber | BadSymbol | StaticIndex | PrivateField | Inherited | GoodInherited;

